sys_ux_data_broker_transform.script:
function transform(input) {

    function getAttestationTasks() {
        var result = [];
        var tasks = [];

        var gr = new GlideRecord("u_attestation_task"); // Changed from cert_task to attestation task
        gr.query();

        while (gr.next()) {
            tasks.push({
                sys_id: gr.getUniqueValue(),
                number: gr.getValue("number"),
                short_description: gr.getValue("short_description"),
                description: gr.getValue("description"),
                state: gr.getDisplayValue("state"),
                assigned_to: gr.getDisplayValue("assigned_to"),
                requested_by: gr.getDisplayValue("requested_by"),
                priority: gr.getDisplayValue("priority"),
                attestation_type: gr.getDisplayValue("attestation_type"),
                due_date: gr.getDisplayValue("due_date"),
                percent_complete: gr.getValue("percent_complete"),
                task_type: "Attestation Task" // Explicitly tag these as Attestation Tasks
            });
        }

        if (tasks.length > 0) {
            result.push({
                additionalFields: tasks
            });
        }

        return result;
    }

    return getAttestationTasks();
}
